    static final class Call implements AutoCloseable {
        final Fixture owner;final String task,run;final int epoch;final RunControl control=new RunControl();final HostToolSupervisor supervisor;final RunJournal journal;final JSONObject arguments=new JSONObject().put("text","Owner explicit call");String operation;
        Call(Fixture owner,boolean capture)throws Exception{this.owner=owner;task=owner.f.tasks.createCapabilityTask("Run the reviewed local tool","").getString("id");owner.f.tasks.initializeExecutionScope(task,8);JSONObject attempt=owner.f.tasks.startAttempt(task,"capabilities",8);run=attempt.getString("runId");epoch=attempt.getInt("coordinatorEpoch");control.bindHostRun(task,run,epoch);owner.f.tasks.authorizeTools(task,run,new JSONArray().put(owner.tool));control.setAuthorityCheck(()->owner.f.tasks.checkCapabilityCurrent(task,run,epoch,owner.tool));supervisor=capture?new HostToolSupervisor(owner.host,owner.f.tasks,task,run,epoch,true,owner.f.tasks.toolOutputFactory(task,run,epoch,control,text->text)):new HostToolSupervisor(owner.host,owner.f.tasks,task,run,epoch,true);supervisor.tools();journal=owner.f.tasks.journal(task,run,epoch,control);}
        JSONObject nativeInput()throws Exception{return new JSONObject().put("id","local_probe").put("tool","lookup").put("expectedInstallationId",owner.installation).put("expectedVersion",owner.registry.getString("version")).put("expectedExecutionIdentity",TaskStore.capabilityFingerprint(owner.registry.getJSONObject("executionBinding"))).put("arguments",new JSONObject(arguments.toString())).put("_operationId",operation).put("_taskId",task).put("_runId",run);}
        JSONObject capability()throws Exception{return new JSONObject().put("feature","plugins").put("command","invoke").put("pluginId","local_probe").put("tool","lookup").put("installationId",owner.installation).put("version",owner.registry.getString("version")).put("expectedExecutionIdentity",TaskStore.capabilityFingerprint(owner.registry.getJSONObject("executionBinding"))).put("nativeProgram",owner.f.plugins.localMcpApprovalSummaryForHost(nativeInput()));}
        JSONObject approve()throws Exception{JSONObject pending=supervisor.execute(owner.tool,new JSONObject(arguments.toString()),control);assertEquals("approval_required",pending.getString("code"));return owner.f.tasks.decideCapabilityApproval(task,pending.getString("approvalId"),true);}
        JSONObject invoke()throws Exception{approve();operation=journal.beginOperation(owner.tool,new JSONObject(arguments.toString()));return executePrepared();}
        JSONObject executePrepared()throws Exception{return supervisor.execute(owner.tool,new JSONObject(arguments.toString()).put("_hostOperationId",operation),control);}
        TaskStore.LocalMcpInvocationRecord record()throws Exception{return owner.f.tasks.localMcpInvocationsForOwner(task).get(0);}
        public void close(){control.cancel();supervisor.close();}
    }
    @Test public void actualPythonCallUsesOneApprovedDebitedOriginalOperationAndCompletesOnlyWithRealCleanup()throws Exception{try(Fixture x=new Fixture();Call call=x.call()){JSONObject result=call.invoke();assertEquals(result.toString(),"response_received",result.getString("status"));assertFalse(result.getBoolean("verified"));assertTrue(result.getJSONObject("toolResult").getJSONArray("content").getJSONObject(0).getString("text").contains("Actual local result🙂"));assertTrue(result.getJSONObject("nativeMcp").getBoolean("processSettled"));assertTrue(result.getJSONObject("nativeMcp").getBoolean("rpcResponseReceived"));assertFalse(result.getJSONObject("nativeMcp").getBoolean("wholeInvocationNotDispatchedConfirmed"));assertTrue(Files.exists(x.copy(call.operation).resolve("RPC_EFFECT")));assertEquals("Owner explicit call",new JSONObject(new String(Files.readAllBytes(x.copy(call.operation).resolve("RPC_EFFECT")),StandardCharsets.UTF_8)).getString("text"));assertEquals(1,x.f.tasks.get(call.task,false).getJSONArray("operations").length());assertEquals(2,x.f.tasks.list().length());assertEquals(1,x.f.tasks.get(call.task,false).getJSONObject("executionScope").getInt("toolsUsed"));assertEquals(0,x.f.tasks.get(call.task,false).getJSONObject("executionScope").getInt("modelCallsUsed"));assertEquals(0,x.f.tasks.get(call.task,false).getJSONObject("executionScope").getLong("deadlineAt"));assertFalse(x.f.tasks.hasUnresolved(call.task));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));String stderr=x.f.runtime.query(call.record().referenceForHost()).json().getString("stderr");assertEquals(1,stderr.split("ACTUAL_METHOD:initialize\n",-1).length-1);assertEquals(1,stderr.split("ACTUAL_METHOD:tools/call\n",-1).length-1);try(Cursor row=x.db().rawQuery("SELECT grant_json FROM runs WHERE run_id=?",new String[]{call.run})){assertTrue(row.moveToFirst());assertEquals(7,new JSONObject(row.getString(0)).getInt("remainingOperations"));}}}
    @Test public void actualNodeProgramUsesTheSameOriginalPipeApprovalAndRealSourceCopy()throws Exception{String source="const fs=require('node:fs'),r=require('node:readline').createInterface({input:process.stdin});fs.writeFileSync('START_EFFECT','startup');r.on('line',line=>{const q=JSON.parse(line);let result;if(q.method==='initialize')result={protocolVersion:'2025-11-25',capabilities:{tools:{}},serverInfo:{name:'Owned Node tool',version:'1'}};else if(q.method==='tools/list')result={tools:[{name:'lookup',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text'],additionalProperties:false}}]};else if(q.method==='tools/call'){fs.writeFileSync('RPC_EFFECT',JSON.stringify(q.params.arguments));result={content:[{type:'text',text:'Actual Node result'}]};}else return;process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:q.id,result})+'\\n');});";try(Fixture x=new Fixture("node","server.js",source);Call call=x.call()){JSONObject result=call.invoke();assertEquals(result.toString(),"response_received",result.getString("status"));assertEquals("node",result.getJSONObject("nativeMcp").getJSONObject("scope").getJSONObject("program").getString("executable"));assertTrue(Files.exists(x.copy(call.operation).resolve("RPC_EFFECT")));assertEquals("pipes",x.f.runtime.query(call.record().referenceForHost()).json().getString("terminalMode"));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void approvalRequiredStartsNeitherAProgramNorAnOperationAndCannotBorrowInstallationJsonAsProof()throws Exception{try(Fixture x=new Fixture();Call call=x.call()){JSONObject pending=call.supervisor.execute(x.tool,new JSONObject(call.arguments.toString()),call.control);assertEquals("approval_required",pending.getString("code"));assertEquals(0,x.f.tasks.get(call.task,false).getJSONArray("operations").length());assertEquals(0,x.f.tasks.localMcpInvocationsForOwner(call.task).size());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertTrue(pending.has("approvalId"));}}
    @Test public void aNativeProgramObjectStillCannotReplaceTheOriginalConsumedApprovalAndLosslessPreparedRow()throws Exception{try(Fixture x=new Fixture();Call call=x.call()){call.approve();call.operation=call.journal.beginOperation(x.tool,new JSONObject(call.arguments.toString()));JSONObject capability=call.capability();try(var program=x.f.plugins.localMcpProgramForTask(call.nativeInput(),x.tool,call.control)){assertThrows(SecurityException.class,()->x.f.tasks.admitLocalMcpInvocationForHost(call.task,call.run,call.epoch,x.tool,call.operation,call.arguments,capability,java.util.UUID.randomUUID().toString(),program,call.control));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertEquals(0,x.f.tasks.localMcpInvocationsForOwner(call.task).size());assertTrue(x.f.tasks.hasUnresolved(call.task));}}}
    @Test public void counterfeitControlOrSecondClaimCannotReuseTheOneOriginalSqlFenceOrCreateAJob()throws Exception{try(Fixture x=new Fixture();Call call=x.call()){call.approve();call.operation=call.journal.beginOperation(x.tool,new JSONObject(call.arguments.toString()));JSONObject capability=call.capability(),approved=x.f.tasks.requireCapabilityApproval(call.task,call.run,x.tool,call.arguments,capability);assertTrue(approved.getBoolean("approved"));try(var program=x.f.plugins.localMcpProgramForTask(call.nativeInput(),x.tool,call.control)){var admission=x.f.tasks.admitLocalMcpInvocationForHost(call.task,call.run,call.epoch,x.tool,call.operation,call.arguments,capability,approved.getString("approvalId"),program,call.control);var prepared=x.f.local.prepareMcpForTask(admission);var actual=prepared.invocationForHost();JSONObject binding=dev.pocketengine.features.local.runtime.NativePipeAdmission.bindingForHost(McpLocalInvocation.pipeIdentityForHost(prepared.scopeForHost()),actual.binding(),actual.executionRef().sourceDigest(),McpLocalInvocation.WRITE_BYTE_LIMIT);RunControl counterfeit=new RunControl();counterfeit.bindHostRun(call.task,call.run,call.epoch);var copied=new dev.pocketengine.features.local.runtime.RuntimeInvocation(actual.exact(),actual.binding(),actual.sourceSnapshot(),counterfeit,()->{},actual.workspace());assertThrows(SecurityException.class,()->x.f.tasks.claimLocalMcpInvocationForHost(admission,copied,binding));x.f.tasks.claimLocalMcpInvocationForHost(admission,actual,binding);assertThrows(SecurityException.class,()->x.f.tasks.claimLocalMcpInvocationForHost(admission,actual,binding));assertEquals(1,x.f.tasks.localMcpInvocationsForOwner(call.task).size());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertThrows(SecurityException.class,()->x.f.tasks.resolveOperation(call.task,call.operation,"not_occurred"));}}}
    @Test public void realOriginalBook9OutputFactoryCapturesTheMatchedRpcWithoutPrivateArgvOrASecondOperation()throws Exception{try(Fixture x=new Fixture();Call call=x.capturedCall()){JSONObject result=call.invoke();assertEquals(result.toString(),"response_received",result.getString("status"));JSONObject capture=result.getJSONObject("outputCapture");assertEquals(capture.toString(),1,capture.getJSONArray("outputRefs").length());JSONObject reference=capture.getJSONArray("outputRefs").getJSONObject(0);assertEquals("MCP_RESULT_JSON",reference.getString("captureKind"));assertEquals(call.task,reference.getString("taskId"));assertEquals(call.operation,reference.getString("operationId"));call.journal.finishOperation(call.operation,result);assertEquals(1,call.record().publicReceiptForHost().getJSONObject("outputCapture").getJSONArray("outputRefs").length());StringBuilder retained=new StringBuilder();try(Cursor row=x.db().rawQuery("SELECT body FROM task_output_chunks",null)){while(row.moveToNext())retained.append(row.getString(0));}assertTrue(retained.toString().contains("Actual local result"));assertTrue(retained.toString().contains("stdio"));assertFalse(retained.toString().contains("--public-mode"));assertEquals(1,x.f.tasks.get(call.task,false).getJSONArray("operations").length());}}
    @Test public void changedInstalledSourceIsTypedNotDispatchedBeforeAnyRuntimeEntryWithoutRefundingTheOriginalDebit()throws Exception{try(Fixture x=new Fixture();Call call=x.call()){Path entry=x.f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(x.f.checkout).resolve("files/server.py");Files.write(entry,"raise Exception('changed source')\n".getBytes(StandardCharsets.UTF_8));JSONObject result=call.invoke();assertEquals("failed",result.getString("status"));assertFalse(result.getBoolean("dispatched"));assertTrue(result.getBoolean("nativeHostNeverEnteredDispatch"));assertFalse(result.getBoolean("nativeProcessReceiptAvailable"));assertEquals(0,x.f.tasks.localMcpInvocationsForOwner(call.task).size());assertFalse(Files.exists(x.copy(call.operation)));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void changedFreshToolDescriptorDoesNotCallTheToolOrRelabelStartupAsNoEffects()throws Exception{try(Fixture x=new Fixture("changed");Call call=x.call()){JSONObject result=call.invoke();assertEquals(result.toString(),"failed",result.getString("status"));assertTrue(result.getBoolean("dispatched"));assertFalse(result.getBoolean("rpcMayHaveDispatched"));assertTrue(result.getJSONObject("nativeMcp").getBoolean("serverStartupEffectMayHaveOccurred"));assertFalse(result.getJSONObject("nativeMcp").getBoolean("wholeInvocationNotDispatchedConfirmed"));assertTrue(Files.exists(x.copy(call.operation).resolve("START_EFFECT")));assertFalse(Files.exists(x.copy(call.operation).resolve("RPC_EFFECT")));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void lostRpcReplyKeepsTheOriginalUnknownAndGenericJournalCannotReplaceItWithSuccess()throws Exception{try(Fixture x=new Fixture("lost");Call call=x.call()){JSONObject result=call.invoke();assertEquals(result.toString(),"unknown",result.getString("status"));assertTrue(result.getBoolean("rpcMayHaveDispatched"));assertTrue(result.getJSONObject("nativeMcp").getBoolean("processSettled"));assertTrue(Files.exists(x.copy(call.operation).resolve("RPC_EFFECT")));call.journal.finishOperation(call.operation,new JSONObject().put("status","completed").put("ok",true));assertTrue(x.f.tasks.hasUnresolved(call.task));assertEquals("unknown",call.record().publicReceiptForHost().getString("status"));JSONObject resolved=x.f.tasks.resolveOperation(call.task,call.operation,"occurred");assertFalse(x.f.tasks.hasUnresolved(call.task));JSONObject receipt=call.record().publicReceiptForHost();assertEquals("owner_reconciled",receipt.getString("status"));assertTrue(receipt.getJSONObject("nativeMcp").getBoolean("serverStartupEffectMayHaveOccurred"));assertFalse(receipt.getBoolean("automaticallyVerified"));assertEquals("paused",resolved.getString("status"));}}
    @Test public void aSettledProcessWithOnlyUnknownBusinessReplyDoesNotBlacklistIndependentNewOwnerCalls()throws Exception{try(Fixture x=new Fixture("lost");Call first=x.call();Call second=x.call()){assertEquals("unknown",first.invoke().getString("status"));assertTrue(x.f.tasks.hasUnresolved(first.task));JSONObject independent=second.invoke();assertEquals(independent.toString(),"unknown",independent.getString("status"));assertTrue(Files.exists(x.copy(second.operation).resolve("RPC_EFFECT")));assertNotEquals(first.task,second.task);assertNotEquals(first.operation,second.operation);assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertEquals(3,x.f.tasks.list().length());}}
    @Test public void originalTaskStopReachesTheSameRunningJobAndGenericResolverCannotEraseItBeforeCleanup()throws Exception{try(Fixture x=new Fixture("block");Call call=x.call()){call.approve();call.operation=call.journal.beginOperation(x.tool,new JSONObject(call.arguments.toString()));ExecutorService worker=Executors.newSingleThreadExecutor();EngineApplication app=new EngineApplication();app.tasks=x.f.tasks;app.features=x.host;try{Future<JSONObject> pending=worker.submit(call::executePrepared);long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);boolean entered=false;while(System.nanoTime()<until){var records=x.f.tasks.localMcpInvocationsForOwner(call.task);if(!records.isEmpty())try{if(x.f.runtime.query(records.get(0).referenceForHost()).json().optString("stderr").contains("CALL_ENTERED")){entered=true;break;}}catch(IllegalArgumentException originalRefNotPublishedYet){}Thread.sleep(20);}assertTrue(entered);assertThrows(SecurityException.class,()->x.f.tasks.resolveOperation(call.task,call.operation,"not_occurred"));assertNull(app.dispatchOwnerAction("stopTask",new JSONObject().put("taskId",call.task)));ExecutionException stopped=assertThrows(ExecutionException.class,()->pending.get(12,TimeUnit.SECONDS));assertTrue(stopped.getCause() instanceof InterruptedException);JSONObject result=call.record().publicReceiptForHost();assertTrue(result.getBoolean("rpcMayHaveDispatched"));long released=System.nanoTime()+TimeUnit.SECONDS.toNanos(4);while(!call.record().publicReceiptForHost().getJSONObject("nativeMcp").optBoolean("processSettled")&&System.nanoTime()<released){x.host.observeLocalMcpInvocationsForOwner(call.task,false);Thread.sleep(20);}assertTrue(call.record().publicReceiptForHost().getJSONObject("nativeMcp").getBoolean("processSettled"));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertEquals(1,x.f.tasks.get(call.task,false).getJSONArray("operations").length());assertEquals(2,x.f.tasks.list().length());}finally{call.control.cancel();worker.shutdownNow();var owned=EngineApplication.class.getDeclaredField("capabilityWorkers");owned.setAccessible(true);((ExecutorService)owned.get(app)).shutdownNow();}}}
    @Test public void actualBoundPrivateReferenceIsAbsentFromTaskUiHistoryAndBook9OperationTextButStillQueryable()throws Exception{try(Fixture x=new Fixture();Call call=x.call()){call.invoke();TaskStore.LocalMcpInvocationRecord privateRecord=call.record();assertEquals("--public-mode",privateRecord.referenceForHost().exact().getJSONObject("payload").getJSONArray("argv").getString(1));JSONObject task=x.f.tasks.get(call.task,false),ui=x.f.tasks.getForUi(call.task,false),history=x.f.tasks.taskHistoryPage(call.task,"operations","",8,65536);for(JSONObject publicView:new JSONObject[]{task,ui,history}){assertFalse(publicView.toString(),publicView.toString().contains("--public-mode"));assertFalse(publicView.toString(),publicView.toString().contains(NativeMcpPrivateFields.HOST_KEY));}JSONObject operation;try(Cursor row=x.db().rawQuery("SELECT tool,arguments,state,receipt,created_at FROM operations WHERE operation_id=?",new String[]{call.operation})){assertTrue(row.moveToFirst());operation=TaskMemoryTrace.storedOperation(call.task,call.run,call.operation,row.getString(0),row.getString(1),row.getString(2),row.getString(3),row.getLong(4));}JSONObject request=new JSONObject().put("taskId",call.task).put("runId",call.run).put("sourceId","task:"+call.task+":operation:"+call.operation).put("revision","sha256:"+TaskStore.capabilityFingerprint(operation)).put("maxChars",12000);JSONObject page=TaskMemoryTrace.operationPage(new JSONObject().put("ownerId","owner").put("spaceId","private"),task,operation,request);assertEquals("current",page.getString("status"));assertFalse(page.getString("body").contains("--public-mode"));assertFalse(page.getString("body").contains(NativeMcpPrivateFields.HOST_KEY));JSONObject originalRun;try(Cursor row=x.db().rawQuery("SELECT task_id,run_id,epoch,status,checkpoint FROM runs WHERE run_id=?",new String[]{call.run})){assertTrue(row.moveToFirst());originalRun=new JSONObject().put("taskId",row.getString(0)).put("runId",row.getString(1)).put("coordinatorEpoch",row.getInt(2)).put("status",row.getString(3)).put("checkpoint",new JSONObject(row.getString(4)));}JSONObject trace=TaskMemoryTrace.page(new JSONObject().put("ownerId","owner").put("spaceId","private"),task,originalRun,java.util.List.of(operation).iterator(),new JSONObject().put("links",new JSONArray()).put("status","current"),new JSONObject().put("section","operations").put("maxChars",12000));assertFalse(trace.toString(),trace.toString().contains("--public-mode"));assertFalse(trace.toString(),trace.toString().contains(NativeMcpPrivateFields.HOST_KEY));JSONObject privateHit=TaskMemoryTrace.page(new JSONObject().put("ownerId","owner").put("spaceId","private"),task,originalRun,java.util.List.of(operation).iterator(),new JSONObject().put("links",new JSONArray()).put("status","current"),new JSONObject().put("section","operations").put("query","--public-mode").put("maxChars",12000));assertEquals(0,privateHit.getInt("matchedCount"));assertTrue(trace.toString().contains("Owner explicit call"));assertTrue(x.f.runtime.query(privateRecord.referenceForHost()).json().getBoolean("resourcesReleased"));JSONObject nested=new JSONObject().put("rpc",new JSONObject().put(NativeMcpPrivateFields.HOST_KEY,"business content")).put(NativeMcpPrivateFields.HOST_KEY,new JSONObject().put("private","host"));JSONObject projected=(JSONObject)NativeMcpPrivateFields.publicArguments(nested);assertEquals("business content",projected.getJSONObject("rpc").getString(NativeMcpPrivateFields.HOST_KEY));assertTrue(nested.has(NativeMcpPrivateFields.HOST_KEY));}}
